#!/usr/bin/env python3
"""Build a single-file offline voter search and slip tool from OCR output."""
import json
from pathlib import Path
OUT = Path("ocr-output")
payload = json.loads((OUT / "voters.json").read_text(encoding="utf-8"))
records = payload.get("records", [])
safe_json = json.dumps(records, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
page = r'''<!doctype html><html lang="hi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ऑफलाइन मतदाता खोज एवं पर्ची</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f2f5f9;color:#172638;font-family:system-ui,"Noto Sans Devanagari","Nirmala UI",sans-serif}header{background:#123d6c;color:white;padding:20px}h1{margin:0 0 5px;font-size:25px}header p{margin:0;color:#dbeafe}.wrap{max-width:1100px;margin:auto;padding:14px}.warn,.panel{background:white;border:1px solid #d8e0ea;border-radius:12px;padding:14px;margin-bottom:12px}.warn{background:#fff8e6;border-color:#edcf7c;font-size:13px}input,select,button{font:inherit;border-radius:9px;padding:11px;border:1px solid #c5d0dd;min-width:0}button{background:#164e83;color:white;border:0;cursor:pointer;font-weight:600}.secondary{background:#e7edf5;color:#18324d}.controls{display:grid;grid-template-columns:1fr 170px;gap:8px}.buttons{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.stats{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.pill{background:#e9f1fa;border-radius:99px;padding:6px 10px;font-size:12px}.layout{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(280px,1fr);gap:12px}.person,.family{border:1px solid #d5dee8;border-radius:10px;padding:12px;margin:8px 0;background:white}.person h3,.family h3{margin:5px 0 8px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:5px;font-size:13px}.meta span{overflow-wrap:anywhere}.muted{color:#66778a;font-size:12px}.member{font-size:13px;padding:5px 0;border-bottom:1px solid #e6ebf1}.empty{padding:25px;text-align:center;color:#64748b}@media(max-width:760px){.layout,.controls{grid-template-columns:1fr}}@media print{header,.warn,.controls,.buttons,.stats,.noprint{display:none!important}body{background:white}.wrap{padding:0}.layout{display:block}.person{break-inside:avoid;border:1px solid #333}.meta{font-size:10px}}
</style></head><body><header><h1>मेरी वोटर पर्ची</h1><p>एक HTML फ़ाइल • ऑफलाइन खोज • परिवार सुझाव • प्रिंट और शेयर</p></header><main class="wrap">
<div class="warn"><b>महत्वपूर्ण:</b> यह PDF से OCR द्वारा निकला मसौदा है। विवरण मूल PDF से जाँचें। सुझाया गया परिवार पूर्ण सत्यापन नहीं है। डेटा इंटरनेट पर अपलोड नहीं होता।</div>
<section class="panel"><div class="controls"><input id="q" placeholder="नाम, पिता/पति, मकान नंबर, EPIC या क्रमांक खोजें"><select id="ward"><option value="">सभी वार्ड</option></select></div><div class="stats"><span class="pill" id="total"></span><span class="pill" id="shown"></span><span class="pill" id="fc"></span></div><div class="buttons"><button id="csv">CSV डाउनलोड</button><button class="secondary" id="print">प्रिंट / PDF</button><button class="secondary" id="clear">खोज साफ़ करें</button></div></section>
<div class="layout"><section class="panel"><h2>मतदाता खोज परिणाम</h2><div id="results"></div></section><aside class="panel"><h2>परिवार / मकान समूह</h2><p class="muted">एक जैसे मकान नंबर को पक्का परिवार न मानें।</p><div id="families"></div></aside></div></main>
<script>
const DATA=__DATA__;
const $=id=>document.getElementById(id);
const norm=s=>String(s||"").toLocaleLowerCase("hi").replace(/\s+/g," ").trim();
const esc=s=>String(s==null?"":s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const ward=r=>((String(r.source_pdf||"").match(/Ward No-?(\d+)/i)||[])[1]||"");
const fk=r=>String(r.family_id||"").trim();
const filtered=()=>{let q=norm($("q").value),w=$("ward").value;return DATA.filter(r=>(!q||norm([r.name,r.relative_name,r.house_no,r.serial_no,r.epic,r.family_id,r.source_pdf].join(" ")).includes(q))&&(!w||ward(r)===w))};
const fields=r=>[["पिता/पति/अन्य",r.relative_name],["मकान नंबर",r.house_no],["आयु",r.age],["लिंग",r.gender],["EPIC",r.epic],["वार्ड",ward(r)],["क्रमांक",r.serial_no],["पृष्ठ",r.page]].filter(x=>String(x[1]||"").trim());
const shareText=r=>["मतदाता पर्ची","नाम: "+(r.name||"स्पष्ट नहीं"),"पिता/पति: "+(r.relative_name||"—"),"मकान नंबर: "+(r.house_no||"—"),"आयु/लिंग: "+(r.age||"—")+" / "+(r.gender||"—"),"EPIC: "+(r.epic||"—"),"वार्ड: "+(ward(r)||"—")+" | क्रमांक: "+(r.serial_no||"—")].join("\n");
function render(){let rows=filtered();$("total").textContent="कुल OCR रिकॉर्ड: "+DATA.length;$("shown").textContent="दिख रहे: "+rows.length;$("fc").textContent="परिवार समूह: "+new Set(rows.map(fk).filter(Boolean)).size;
$("results").innerHTML=rows.length?rows.slice(0,300).map(r=>'<article class="person"><div class="muted">वार्ड '+esc(ward(r)||"—")+' • क्रमांक '+esc(r.serial_no||"—")+' • '+esc(fk(r)?"परिवार "+fk(r):"परिवार पुष्टि शेष")+'</div><h3>'+esc(r.name||"नाम OCR से स्पष्ट नहीं")+'</h3><div class="meta">'+fields(r).map(x=>'<span><b>'+esc(x[0])+':</b> '+esc(x[1])+'</span>').join("")+'</div><div class="buttons"><button onclick="shareRecord('+DATA.indexOf(r)+')">WhatsApp / शेयर</button><button class="secondary" onclick="printRecord('+DATA.indexOf(r)+')">पर्ची प्रिंट</button></div><div class="muted">स्रोत: '+esc(r.source_pdf||"")+' • पृष्ठ '+esc(r.page||"—")+'</div></article>').join(""):'<div class="empty">कोई रिकॉर्ड नहीं मिला।</div>';
if(rows.length>300)$("results").insertAdjacentHTML("beforeend",'<div class="muted">पहले 300 परिणाम दिखाए। खोज और संकरी करें।</div>');
let groups={};rows.forEach(r=>{if(fk(r))(groups[fk(r)]||(groups[fk(r)]=[])).push(r)});
let h=Object.keys(groups).sort().map(k=>'<div class="family"><h3>'+esc(k)+' ('+groups[k].length+' सदस्य)</h3>'+groups[k].map(r=>'<div class="member"><b>'+esc(r.name||"नाम स्पष्ट नहीं")+'</b><br><span class="muted">रिश्ता: '+esc(r.relative_name||"—")+' • मकान: '+esc(r.house_no||"—")+' • क्रमांक: '+esc(r.serial_no||"—")+'</span></div>').join("")+'</div>').join("");
let houses={};rows.filter(r=>r.house_no).forEach(r=>{let k=String(r.house_no).trim();(houses[k]||(houses[k]=[])).push(r)});
let hg=Object.entries(houses).filter(x=>x[1].length>1).slice(0,40);if(hg.length)h+='<h3>एक जैसे मकान नंबर — केवल सुझाव</h3>'+hg.map(x=>'<div class="family"><b>मकान '+esc(x[0])+' ('+x[1].length+' रिकॉर्ड)</b><div class="muted">इन्हें स्वतः एक परिवार न मानें।</div>'+x[1].slice(0,12).map(r=>'<div class="member">'+esc(r.name||"नाम स्पष्ट नहीं")+' — '+esc(r.relative_name||"—")+'</div>').join("")+'</div>').join("");
$("families").innerHTML=h||'<div class="empty">इस खोज में परिवार समूह नहीं मिले।</div>'}
window.shareRecord=async i=>{let r=DATA[i],t=shareText(r);if(navigator.share){try{await navigator.share({title:"मतदाता पर्ची",text:t});return}catch(e){}}window.open("https://wa.me/?text="+encodeURIComponent(t),"_blank")};
window.printRecord=i=>{let r=DATA[i],w=window.open("","_blank","width=650,height=750");if(!w){alert("पॉप-अप की अनुमति दें।");return}w.document.write('<html lang="hi"><meta charset="utf-8"><title>मतदाता पर्ची</title><style>body{font-family:system-ui,"Noto Sans Devanagari",sans-serif;padding:20px}.slip{border:2px solid #172638;padding:18px;max-width:500px;margin:auto}.line{padding:7px 0;border-bottom:1px solid #ddd}</style><div class="slip"><h2>मतदाता पर्ची</h2>'+[["नाम",r.name],["पिता/पति/अन्य",r.relative_name],["मकान नंबर",r.house_no],["आयु",r.age],["लिंग",r.gender],["EPIC नंबर",r.epic],["वार्ड",ward(r)],["क्रमांक",r.serial_no],["स्रोत PDF",r.source_pdf],["पृष्ठ",r.page]].filter(x=>String(x[1]||"").trim()).map(x=>'<div class="line"><b>'+esc(x[0])+':</b> '+esc(x[1])+'</div>').join("")+'<p style="font-size:10px">OCR मसौदा — मूल सूची से विवरण जाँचें।</p></div><script>window.onload=()=>window.print()<\/script></html>');w.document.close()};
$("q").addEventListener("input",render);$("ward").addEventListener("change",render);$("clear").onclick=()=>{$("q").value="";$("ward").value="";render()};$("print").onclick=()=>window.print();
$("csv").onclick=()=>{let cols=["serial_no","name","relative_name","house_no","age","gender","epic","family_id","source_pdf","page","ocr_confidence","raw_ocr"];let quote=v=>'"'+String(v==null?"":v).replace(/"/g,'""')+'"';let data="\ufeff"+[cols.join(","),...filtered().map(r=>cols.map(k=>quote(r[k])).join(","))].join("\r\n");let a=document.createElement("a");a.href=URL.createObjectURL(new Blob([data],{type:"text/csv;charset=utf-8"}));a.download="voter-search-results.csv";a.click();URL.revokeObjectURL(a.href)};
[...new Set(DATA.map(ward).filter(Boolean))].sort((a,b)=>+a-+b).forEach(v=>{let o=document.createElement("option");o.value=v;o.textContent="वार्ड "+v;$("ward").appendChild(o)});render();
</script></body></html>'''
(OUT / "voter-search-offline.html").write_text(page.replace("__DATA__", safe_json), encoding="utf-8")
print("Created voter-search-offline.html with", len(records), "OCR records; verify against source PDFs.")
